#!/bin/sh
# Create ./.env with fresh random secrets for local development. Never overwrites, never prints secrets.
set -eu
cd "$(dirname "$0")/.."
if [ -e .env ]; then
  echo ".env already exists; leaving it alone."
  exit 0
fi
rand() { od -An -N"$1" -tx1 /dev/urandom | tr -d ' \n'; }
pg=$(rand 12)
umask 077
cat > .env <<ENV
# Local dev only. Generated by scripts/setup-env.sh; not for production.
PYTHONUNBUFFERED=0
REDASH_LOG_LEVEL=INFO
REDASH_REDIS_URL=redis://redis:6379/0
REDASH_COOKIE_SECRET=$(rand 24)
REDASH_SECRET_KEY=$(rand 24)
POSTGRES_PASSWORD=$pg
REDASH_DATABASE_URL=postgresql://postgres:$pg@postgres/postgres
REDASH_ENFORCE_CSRF=true
ADMIN_PASSWORD=$(rand 8)
ENV
echo "Created .env (admin password is in ADMIN_PASSWORD)."
